import{_ as u,B as i,o,c as p,a8 as n,d as m,w as s,f as l,E as r,af as h,a}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse(`{"title":"Users","description":"The Users module is Xila's in-memory identity and group membership registry.","frontmatter":{"layout":"doc","docType":"explanation","description":"The Users module is Xila's in-memory identity and group membership registry."},"headers":[],"relativePath":"explanation/architecture/subsystems/users.md","filePath":"explanation/architecture/subsystems/users.md","lastUpdated":1792485373000}`),g={name:"explanation/architecture/subsystems/users.md"};function f(y,e,b,k,_,x){const d=i("Mermaid"),c=i("CodeReference"),t=i("HostReference");return o(),p("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792485373000"},[e[3]||(e[3]=n('<h1 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h1><p>The Users module is Xila&#39;s in-memory identity and group membership registry.</p><h2 id="role-in-system" tabindex="-1">Role in system <a class="header-anchor" href="#role-in-system" aria-label="Permalink to &quot;Role in system&quot;">​</a></h2><ul><li>Supplies user/group identity data for permission checks and ownership metadata.</li><li>Allocates and resolves typed identifiers used by task and VFS layers.</li><li>Guarantees root account/group bootstrap at manager initialization.</li></ul><h2 id="responsibilities-and-boundaries" tabindex="-1">Responsibilities and boundaries <a class="header-anchor" href="#responsibilities-and-boundaries" aria-label="Permalink to &quot;Responsibilities and boundaries&quot;">​</a></h2><p><strong>In scope</strong></p><ul><li>User/group insertion and lookup.</li><li>Membership tracking (<code>add_to_group</code>, <code>is_in_group</code>, <code>get_user_groups</code>).</li><li>Identifier and name resolution APIs.</li></ul><p><strong>Out of scope</strong></p><ul><li>Credential verification policy (current <code>check_credentials</code> is placeholder-like).</li><li>Authentication/session/token management.</li><li>Persistent storage (state is runtime memory only).</li></ul><h2 id="internal-architecture" tabindex="-1">Internal architecture <a class="header-anchor" href="#internal-architecture" aria-label="Permalink to &quot;Internal architecture&quot;">​</a></h2><ul><li>Explicit <code>users::Manager::new()</code> with references passed to VFS, authentication, and executables.</li><li>Internal <code>RwLock</code> protects: <ul><li><code>users: BTreeMap&lt;UserIdentifier, InternalUser&gt;</code>,</li><li><code>groups: BTreeMap&lt;GroupIdentifier, InternalGroup&gt;</code>.</li></ul></li><li><code>InternalUser</code> stores name + primary group.</li><li><code>InternalGroup</code> stores group name + membership set (<code>BTreeSet&lt;UserIdentifier&gt;</code>).</li></ul><p><strong>Contract vs implementation</strong></p><ul><li><strong>Contract</strong>: typed identifier APIs and membership/name lookup behavior.</li><li><strong>Implementation</strong>: exact map/set layout, root bootstrap details, allocation scan strategy.</li></ul>',13)),(o(),m(h,null,{default:s(()=>[r(d,{id:"mermaid-121",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Clients%40%7B%20shape%3A%20processes%2C%20label%3A%20%22Modules%20%2F%20executables%22%20%7D%0A%20%20%20%20Auth%5Bauthentication%20crate%5D%0A%20%20%20%20UsersAPI%5Busers%20module%20API%5D%0A%20%20%20%20Manager%5BExplicit%20Users%20Manager%5D%0A%20%20%20%20Lock%5BRwLock%5D%0A%20%20%20%20UsersMap%5B(users%20map)%5D%0A%20%20%20%20GroupsMap%5B(groups%20map)%5D%0A%0A%20%20%20%20Clients%20--%3E%7Cquery%20%2F%20permission%20checks%7C%20UsersAPI%0A%20%20%20%20Auth%20--%3E%7Ccreate%2Fload%20accounts%7C%20UsersAPI%0A%20%20%20%20UsersAPI%20--%3E%20Manager%0A%20%20%20%20Manager%20--%3E%20Lock%0A%20%20%20%20Lock%20--%3E%20UsersMap%0A%20%20%20%20Lock%20--%3E%20GroupsMap%0A%20%20%20%20UsersMap%20--%3E%7Cprimary_group%20id%7C%20GroupsMap%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<h2 id="lifecycle-and-execution-model" tabindex="-1">Lifecycle and execution model <a class="header-anchor" href="#lifecycle-and-execution-model" aria-label="Permalink to &quot;Lifecycle and execution model&quot;">​</a></h2><ol><li>Construct a manager; root user/group are inserted immediately.</li><li>Allocate identifiers for additional users/groups.</li><li>Register users/groups and membership before launching constrained workloads.</li><li>Query identity/membership during runtime from task/VFS policy paths.</li></ol><h2 id="data-control-flow" tabindex="-1">Data/control flow <a class="header-anchor" href="#data-control-flow" aria-label="Permalink to &quot;Data/control flow&quot;">​</a></h2><ul><li>Task metadata uses user/group identifiers from this module.</li><li>VFS permission checks use the supplied users manager&#39;s <code>is_in_group(...)</code> method.</li><li>Name-based resolution provides bridge between human-readable config and typed runtime ids.</li></ul><h2 id="concurrency-and-synchronization-model" tabindex="-1">Concurrency and synchronization model <a class="header-anchor" href="#concurrency-and-synchronization-model" aria-label="Permalink to &quot;Concurrency and synchronization model&quot;">​</a></h2><ul><li>Single <code>RwLock</code> guards all user/group data.</li><li>Read operations scale concurrently.</li><li>Mutating operations (add user/group/member) take write lock and enforce duplicate checks.</li></ul><h2 id="dependency-model" tabindex="-1">Dependency model <a class="header-anchor" href="#dependency-model" aria-label="Permalink to &quot;Dependency model&quot;">​</a></h2><ul><li>Used directly by <a href="/explanation/architecture/subsystems/task.html">Task</a> and <a href="/explanation/architecture/subsystems/virtual_file_system.html">Virtual file system</a>.</li><li>Higher-level authentication crate composes over this module rather than embedding inside it.</li></ul><h2 id="failure-semantics-and-recovery-behavior" tabindex="-1">Failure semantics and recovery behavior <a class="header-anchor" href="#failure-semantics-and-recovery-behavior" aria-label="Permalink to &quot;Failure semantics and recovery behavior&quot;">​</a></h2><ul><li>Duplicate identifiers/names return explicit duplicate errors.</li><li>Invalid user/group references return typed invalid-identifier errors.</li><li>Identifier allocation fails with <code>TooManyUsers</code> / <code>TooManyGroups</code> on range exhaustion.</li></ul><h2 id="extension-points" tabindex="-1">Extension points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension points&quot;">​</a></h2><ul><li>Add richer metadata per user/group while preserving typed id model.</li><li>Add batch APIs for provisioning workflows.</li><li>Add persistent snapshot/load layers in higher-level components.</li></ul><h2 id="known-limitations-and-trade-offs" tabindex="-1">Known limitations and trade-offs <a class="header-anchor" href="#known-limitations-and-trade-offs" aria-label="Permalink to &quot;Known limitations and trade-offs&quot;">​</a></h2><ul><li>Runtime-only storage; no built-in persistence.</li><li>Current credential-check method is not a complete authentication implementation.</li><li>One manager lock coordinates its identity registry.</li></ul><p>Persistent groups are loaded before users. Registering a restored user tolerates primary-group membership already present in the saved group; duplicate user identifiers and names still fail.</p><h2 id="registry-invariants-and-implementation-caveats" tabindex="-1">Registry invariants and implementation caveats <a class="header-anchor" href="#registry-invariants-and-implementation-caveats" aria-label="Permalink to &quot;Registry invariants and implementation caveats&quot;">​</a></h2><p>The manager stores users and groups in <code>BTreeMap</code> collections behind an asynchronous <code>RwLock&lt;CriticalSectionRawMutex, _&gt;</code>; each group&#39;s membership is a <code>BTreeSet&lt;UserIdentifier&gt;</code>. <code>Manager::new()</code> creates the root user and root group. Identifier allocation helpers scan from their minimum value until an unused identifier is found and report <code>TooManyUsers</code> or <code>TooManyGroups</code> at the limit.</p><p><code>add_user(id, name, primary_group)</code> rejects duplicate user IDs and names. The implementation inserts the user into the map before resolving the primary group. <strong>A missing primary group therefore returns <code>InvalidGroupIdentifier</code> after the user record was inserted</strong>, so callers should validate that the group exists before calling <code>add_user</code>. The group membership insertion is idempotent to support restoration of previously loaded membership. The initial root group is constructed with an empty membership set, so <code>is_in_group(UserIdentifier::ROOT, GroupIdentifier::ROOT)</code> does not automatically return true solely because the root user has that primary group.</p><p><code>add_group(id, name, users)</code> rejects duplicate group IDs and names, and initializes membership from the supplied slice. <code>add_to_group()</code> checks group existence, then inserts a user identifier; it does not itself verify that the user exists. Membership queries read the group sets, not a separately maintained reverse index.</p><p><code>check_credentials()</code> currently returns <code>true</code> unconditionally. <strong>Do not treat it as an authentication or authorization boundary.</strong> Credential verification and session policy must be provided by the appropriate authentication component. The registry itself is in-memory; persistence is handled by surrounding system integration rather than automatically by <code>Manager</code>.</p><h3 id="implementation-references" tabindex="-1">Implementation references <a class="header-anchor" href="#implementation-references" aria-label="Permalink to &quot;Implementation references&quot;">​</a></h3>',21)),a("ul",null,[a("li",null,[r(c,{path:"subsystems/users/src/manager.rs"})]),a("li",null,[r(t,{crate:"users",kind:"struct",symbol:"Manager"})]),e[1]||(e[1]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/authentication.html"},"Authentication library")],-1))]),e[5]||(e[5]=a("h2",{id:"references-see-also",tabindex:"-1"},[l("References / See also "),a("a",{class:"header-anchor",href:"#references-see-also","aria-label":'Permalink to "References / See also"'},"​")],-1)),a("ul",null,[a("li",null,[r(t,{crate:"users"})]),e[2]||(e[2]=a("li",null,[a("a",{href:"/explanation/architecture/libraries/authentication.html"},"Authentication (crate)")],-1))])])}const I=u(g,[["render",f]]);export{v as __pageData,I as default};
